// Extract workflow run info
const payload = $input.item.json.body;
const workflowRun = payload.workflow_run;

return {
  run_id: workflowRun.id,
  repo_full_name: payload.repository.full_name,
  repo_owner: payload.repository.owner.login,
  repo_name: payload.repository.name,
  workflow_name: workflowRun.name,
  branch: workflowRun.head_branch,
  commit_sha: workflowRun.head_sha.substring(0, 8),
  commit_message: workflowRun.head_commit?.message || 'N/A',
  actor: workflowRun.actor.login,
  run_url: workflowRun.html_url,
  jobs_url: workflowRun.jobs_url,
  logs_url: workflowRun.logs_url,
  created_at: workflowRun.created_at,
  updated_at: workflowRun.updated_at
};

// Find failed jobs and extract error info
const jobs = $input.item.json.jobs || [];
const runInfo = $('Extract Run Info').item.json;

const failedJobs = jobs.filter(job => job.conclusion === 'failure');

const failedSteps = [];
for (const job of failedJobs) {
  const steps = job.steps || [];
  for (const step of steps) {
    if (step.conclusion === 'failure') {
      failedSteps.push({
        job_name: job.name,
        job_id: job.id,
        step_name: step.name,
        step_number: step.number,
        started_at: step.started_at,
        completed_at: step.completed_at
      });
    }
  }
}

return {
  ...runInfo,
  failed_jobs: failedJobs.map(j => ({
    id: j.id,
    name: j.name,
    conclusion: j.conclusion,
    html_url: j.html_url
  })),
  failed_steps: failedSteps,
  total_failed_jobs: failedJobs.length,
  total_failed_steps: failedSteps.length,
  first_failed_job_id: failedJobs[0]?.id,
  first_failed_job_name: failedJobs[0]?.name,
  first_failed_step: failedSteps[0]?.step_name || 'Unknown'
};

// Extract relevant error lines from logs
const logs = $input.item.json.data || $input.item.json || '';
const logsText = typeof logs === 'string' ? logs : JSON.stringify(logs);
const failureInfo = $('Analyze Failures').item.json;

// Find error patterns in logs
const errorPatterns = [
  /error[:\s]/gi,
  /failed[:\s]/gi,
  /exception[:\s]/gi,
  /fatal[:\s]/gi,
  /cannot find/gi,
  /not found/gi,
  /permission denied/gi,
  /exit code [1-9]/gi,
  /npm ERR!/gi,
  /TypeError:/gi,
  /SyntaxError:/gi,
  /ModuleNotFoundError:/gi
];

const lines = logsText.split('\n');
const errorLines = [];
const contextLines = 3;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const isError = errorPatterns.some(pattern => pattern.test(line));

  if (isError) {
    // Get context (lines before and after)
    const start = Math.max(0, i - contextLines);
    const end = Math.min(lines.length, i + contextLines + 1);
    const context = lines.slice(start, end).join('\n');

    if (!errorLines.includes(context)) {
      errorLines.push(context);
    }

    // Limit to 5 error blocks
    if (errorLines.length >= 5) break;
  }
}

// Truncate logs for summary (last 100 lines)
const lastLines = lines.slice(-100).join('\n');

// Create error summary
const errorSummary = errorLines.length > 0 
  ? errorLines.join('\n---\n')
  : lastLines.substring(0, 2000);

return {
  ...failureInfo,
  error_summary: errorSummary.substring(0, 3000),
  error_count: errorLines.length,
  logs_truncated: logsText.length > 3000
};

// Format Slack message
const data = $input.item.json;

const failedJobsList = data.failed_jobs
  .map(j => `• <${j.html_url}|${j.name}>`)
  .join('\n');

const failedStepsList = data.failed_steps
  .slice(0, 5)
  .map(s => `• ${s.job_name} → ${s.step_name}`)
  .join('\n');

return {
  ...data,
  slack_title: `❌ Pipeline Failed: ${data.repo_name}`,
  slack_text: `Workflow *${data.workflow_name}* failed on branch \`${data.branch}\``,
  slack_fields: [
    { title: 'Repository', value: data.repo_full_name, short: true },
    { title: 'Branch', value: data.branch, short: true },
    { title: 'Commit', value: `\`${data.commit_sha}\` ${data.commit_message.split('\n')[0].substring(0, 50)}`, short: false },
    { title: 'Triggered by', value: data.actor, short: true },
    { title: 'Failed Jobs', value: data.total_failed_jobs.toString(), short: true }
  ],
  slack_failed_jobs: failedJobsList,
  slack_failed_steps: failedStepsList,
  slack_error_block: '```' + data.error_summary.substring(0, 2500) + '```'
};
